ALTER TABLE "chats" DROP CONSTRAINT "chats_execution_root_check";--> statement-breakpoint
ALTER TABLE "chats" ADD CONSTRAINT "chats_execution_root_check" CHECK (("chats"."context_kind" = 'project' AND "chats"."project_id" IS NOT NULL AND "chats"."active_worktree_id" IS NOT NULL AND "chats"."active_scratch_root_id" IS NULL AND "chats"."worktree_mode" IN ('agent-managed', 'pinned')) OR ("chats"."context_kind" = 'standalone' AND "chats"."project_id" IS NULL AND "chats"."active_worker_id" IS NOT NULL AND "chats"."active_worktree_id" IS NULL AND "chats"."active_scratch_root_id" IS NOT NULL AND "chats"."worktree_mode" IS NULL AND "chats"."experience" = 'agent' AND "chats"."custom_subagent_model" = false AND "chats"."subagent_model_id" IS NULL AND "chats"."subagent_reasoning_effort" IS NULL AND "chats"."plan_mode" = 'default' AND "chats"."protected_plan" IS NULL AND "chats"."has_pending_plan_question" = false));
